32	    {
33	        WhichDataType which(expression_return);
34	
35	        if (which.isUInt8() || which.isInt8())
36	            return std::make_shared<DataTypeArray>(std::make_shared<DataTypeInt16>());
37	
38	        if (which.isUInt16() || which.isInt16())
39	            return std::make_shared<DataTypeArray>(std::make_shared<DataTypeInt32>());
