42	            return std::make_shared<DataTypeArray>(std::make_shared<DataTypeInt64>());
43	
44	        if (which.isFloat32() || which.isFloat64())
45	            return std::make_shared<DataTypeArray>(std::make_shared<DataTypeFloat64>());
46	
47	        if (which.isDecimal())
48	            return std::make_shared<DataTypeArray>(expression_return);
