54	    template <typename Element, typename Result>
55	    static void NO_SANITIZE_UNDEFINED impl(const Element * __restrict src, Result * __restrict dst, size_t begin, size_t end)
56	    {
57	        /// First element is zero, then the differences of ith and i-1th elements.
58	
59	        Element prev{};
60	        for (size_t pos = begin; pos < end; ++pos)
61	        {
62	            if (pos == begin)
63	            {
64	                dst[pos] = {};
65	                prev = src[pos];
66	            }
67	            else
68	            {
69	                Element curr = src[pos];
70	
71	                if constexpr (is_decimal<Element>)
72	                {
73	                    using ResultNativeType = typename Result::NativeType;
74	
75	                    ResultNativeType result_value;
76	                    bool overflow = common::subOverflow(
77	                        static_cast<ResultNativeType>(curr.value),
78	                        static_cast<ResultNativeType>(prev.value),
79	                        result_value);
80	                    if (overflow)
81	                        throw Exception(ErrorCodes::DECIMAL_OVERFLOW, "Decimal math overflow");
82	
83	                    dst[pos] = Result(result_value);
84	                }
85	                else
86	                {
87	                    dst[pos] = curr - prev;
88	                }
89	
90	                prev = curr;
91	            }
92	        }
93	    }
