108	        const typename ColVecType::Container & data = column->getData();
109	
110	        typename ColVecResult::MutablePtr res_nested;
111	        if constexpr (is_decimal<Element>)
112	            res_nested = ColVecResult::create(0, column->getScale());
113	        else
114	            res_nested = ColVecResult::create();
115	
116	        typename ColVecResult::Container & res_values = res_nested->getData();
117	        res_values.resize(data.size());
